<?php

namespace App\Http\Controllers;

use App\Actions\StudyPlans\ImportStudyPlanFromJson;
use App\Http\Requests\StudyPlanImportRequest;
use Illuminate\Http\RedirectResponse;
use Inertia\Inertia;
use Inertia\Response;

class StudyPlanImportController extends Controller
{
    /**
     * Show the import page with the AI prompt template and the paste form.
     */
    public function create(): Response
    {
        return Inertia::render('study-plans/import');
    }

    /**
     * Import a plan from a JSON payload, typically generated by an AI chat
     * from the prompt template shown on the import page.
     */
    public function store(StudyPlanImportRequest $request, ImportStudyPlanFromJson $importStudyPlanFromJson): RedirectResponse
    {
        $studyPlan = $importStudyPlanFromJson->handle($request->validated('data'), $request->user());

        Inertia::flash('toast', ['type' => 'success', 'message' => __('Plano de estudos importado.')]);

        return to_route('study-plans.show', $studyPlan);
    }
}
